from typing import Dict

def store_info_in_header(
    info_type: str, info_content: str, header: Dict[str, str]
) -> Dict[str, str]:
    type_to_key = {'lang': 'Accept-Language', 'encoding': 'Accept-Encoding', 'cache': 'Cache-Control'}

    if not isinstance(info_type, str) or info_type not in type_to_key:
        return header

    if not isinstance(info_content, str):
        return header

    content = info_content.strip()
    if not content:
        return header

    key = type_to_key[info_type]
    updated_header = header.copy()
    updated_header[key] = content
    return updated_header

# Example usage and testing
header = {}
print(store_info_in_header('lang', 'en-US', header))  # Should set Accept-Language: en-US
assert store_info_in_header('invalid', 'test', {}) == {}  # Invalid type returns original
